export default ListingClient;

"use client";

import { SafeUser } from "@/types";
import Container from "../Container";
import Logo from "./Logo";
import Search from "./Search";
import UserMenu from "./UserMenu";
import { useRouter, usePathname } from "next/navigation";
import useLoginModel from "@/hook/useLoginModal";
import useRentModal from "@/hook/useRentModal";
import useLanguageModal from "@/hook/useLanguageModal";
import useLanguage from "@/hook/useLanguage";
import useSearchModal from "@/hook/useSearchModal";
import { translations } from "@/lib/translations";
import { useCallback, useState, useRef, useEffect } from "react";
import { MdLanguage } from "react-icons/md";
import { TbHome, TbBalloon } from "react-icons/tb";
import { BiSearch } from "react-icons/bi";

type Props = {
  currentUser?: SafeUser | null;
};

function Navbar({ currentUser }: Props) {
  const router = useRouter();
  const loginModel = useLoginModel();
  const rentModel = useRentModal();
  const languageModal = useLanguageModal();
  const searchModal = useSearchModal();
  const { language } = useLanguage();
  const t = translations[language] || translations.fr;
  const pathname = usePathname();

  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 20) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const houseVideoRef = useRef<HTMLVideoElement>(null);
  const balloonVideoRef = useRef<HTMLVideoElement>(null);

  const onRent = useCallback(() => {
    if (!currentUser) {
      return loginModel.onOpen();
    }

    rentModel.onOpen();
  }, [currentUser, loginModel, rentModel]);

  return (
    <div className="fixed top-0 left-0 w-full bg-white z-50 transition-all duration-300 border-b-[1px] shadow-sm">
      <div className={`transition-all duration-300 ${isScrolled ? "py-2" : "py-4"}`}>
        <Container>
          <div className="flex flex-row items-center justify-between gap-3 md:gap-0 relative h-[50px]">
            <div className="flex-none">
              <Logo />
            </div>

            {/* Center Area : Switcher & Compact Search */}
            <div className="hidden md:flex absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 items-center justify-center">

              {/* The Switcher: Logements / Expériences */}
              <div className={`flex flex-row items-center gap-8 text-[17px] text-[#717171] transition-all duration-300 ${isScrolled ? "opacity-0 scale-95 pointer-events-none absolute pt-4" : "opacity-100 scale-100 relative pointer-events-auto"}`}>

                {/* Logements */}
                <div
                  onClick={() => {
                    router.push("/");
                    if (houseVideoRef.current) {
                      houseVideoRef.current.currentTime = 0;
                      houseVideoRef.current.play();
                    }
                  }}
                  onMouseEnter={() => {
                    if (houseVideoRef.current) {
                      houseVideoRef.current.currentTime = 0;
                      houseVideoRef.current.play();
                    }
                  }}
                  className={`cursor-pointer transition relative pb-2 flex flex-row items-center gap-2 hover:text-[#222222] hover:-translate-y-[1px] ${pathname === "/" ? "text-[#222222] font-semibold after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-full after:h-[2px] after:bg-[#222222]" : "font-medium"}`}
                >
                  <video
                    ref={houseVideoRef}
                    autoPlay
                    muted
                    playsInline
                    className="w-10 h-10 object-cover bg-transparent outline-none drop-shadow-sm"
                  >
                    <source src="https://a0.muscache.com/videos/search-bar-icons/webm/house-selected.webm#t=0.001" type="video/webm" />
                    <source src="https://a0.muscache.com/videos/search-bar-icons/hevc/house-selected.mov#t=0.001" type="video/mp4" />
                  </video>
                  <span className="tracking-wide">{t.logements}</span>
                </div>

                {/* Expériences */}
                <div
                  onClick={() => {
                    router.push("/experiences");
                    if (balloonVideoRef.current) {
                      balloonVideoRef.current.currentTime = 0;
                      balloonVideoRef.current.play();
                    }
                  }}
                  onMouseEnter={() => {
                    if (balloonVideoRef.current) {
                      balloonVideoRef.current.currentTime = 0;
                      balloonVideoRef.current.play();
                    }
                  }}
                  className={`cursor-pointer transition relative pb-2 flex flex-row items-center gap-2 hover:text-[#222222] hover:-translate-y-[1px] ${pathname === "/experiences" ? "text-[#222222] font-semibold after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-full after:h-[2px] after:bg-[#222222]" : "font-medium"}`}
                >
                  <video
                    ref={balloonVideoRef}
                    autoPlay
                    muted
                    playsInline
                    className="w-10 h-10 object-cover bg-transparent outline-none drop-shadow-sm"
                  >
                    <source src="https://a0.muscache.com/videos/search-bar-icons/webm/balloon-twirl.webm" type="video/webm" />
                    <source src="https://a0.muscache.com/videos/search-bar-icons/hevc/balloon-twirl.mov" type="video/mp4" />
                  </video>
                  <span className="tracking-wide">{t.experiences}</span>
                </div>

              </div>

              {/* Compact Search Bar (Visible only when scrolled) */}
              <div className={`flex w-auto justify-center transition-all duration-300 ${isScrolled ? "opacity-100 scale-100 translate-y-0 visible relative pointer-events-auto" : "opacity-0 scale-95 translate-y-4 invisible absolute pointer-events-none"}`}>
                 <div
                   onClick={searchModal.onOpen}
                   className="border-[1px] w-full py-1 pl-2 pr-1 rounded-full shadow-md hover:shadow-lg transition cursor-pointer flex flex-row items-center justify-between text-[15px] font-medium text-gray-800 bg-white"
                 >
                   <div className="flex flex-row items-center gap-2 px-3 hover:bg-neutral-100 rounded-full transition py-2">
                     <video
                       autoPlay
                       muted
                       playsInline
                       className="w-5 h-5 object-cover bg-transparent outline-none drop-shadow-sm"
                     >
                       <source src="https://a0.muscache.com/videos/search-bar-icons/webm/house-selected.webm#t=0.001" type="video/webm" />
                       <source src="https://a0.muscache.com/videos/search-bar-icons/hevc/house-selected.mov#t=0.001" type="video/mp4" />
                     </video>
                     <span className="font-semibold">{t.anywhere || "N'importe où"}</span>
                   </div>
                   <div className="px-4 border-l-[1px] border-r-[1px] border-gray-200 flex-1 text-center py-2 hover:bg-neutral-100 rounded-full transition font-semibold">
                     Dates flexibles
                   </div>
                   <div className="flex flex-row items-center gap-3 pl-4 pr-1 py-1 hover:bg-neutral-100 rounded-full transition">
                     <span className="text-gray-500">{t.addguests || "Ajouter des voyageurs"}</span>
                     <div className="p-2 bg-rose-500 rounded-full text-white inline-flex items-center justify-center">
                       <BiSearch size={16} className="font-bold" />
                     </div>
                   </div>
                 </div>
              </div>
            </div>

            <div className="flex flex-row items-center gap-3 flex-none">
              <div
                onClick={onRent}
                className="hidden md:block text-sm font-semibold py-3 px-4 rounded-full hover:bg-neutral-100 transition cursor-pointer"
              >
                {t.host}
              </div>
              <div
                onClick={languageModal.onOpen}
                className="p-3 hover:bg-neutral-100 rounded-full transition cursor-pointer"
                title={language === "fr" ? "Changer la langue" : "Change language"}
              >
                <MdLanguage size={18} />
              </div>
              <UserMenu currentUser={currentUser} />
            </div>
          </div>

          {/* Big Search Bar Area (Hidden when scrolled) */}
          <div className={`flex justify-center transition-all duration-300 origin-top overflow-hidden flex-col ${isScrolled ? "h-0 opacity-0 my-0 scale-y-0" : "h-[90px] opacity-100 my-2 md:my-6 scale-y-100"}`}>
             <Search />
          </div>

        </Container>
      </div>
    </div>
  );
}

export default Navbar;

"use client";

import { SafeUser } from "@/types";
import Container from "../Container";
import Logo from "./Logo";
import Search from "./Search";
import UserMenu from "./UserMenu";
import { useRouter, usePathname } from "next/navigation";
import useLoginModel from "@/hook/useLoginModal";
import useRentModal from "@/hook/useRentModal";
import useLanguageModal from "@/hook/useLanguageModal";
import useLanguage from "@/hook/useLanguage";
import useSearchModal from "@/hook/useSearchModal";
import { translations } from "@/lib/translations";
import { useCallback, useState, useRef, useEffect } from "react";
import { MdLanguage } from "react-icons/md";
import { TbHome, TbBalloon } from "react-icons/tb";
import { BiSearch } from "react-icons/bi";

type Props = {
  currentUser?: SafeUser | null;
};

function Navbar({ currentUser }: Props) {
  const router = useRouter();
  const loginModel = useLoginModel();
  const rentModel = useRentModal();
  const languageModal = useLanguageModal();
  const searchModal = useSearchModal();
  const { language } = useLanguage();
  const t = translations[language] || translations.fr;
  const pathname = usePathname();

  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 20) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const houseVideoRef = useRef<HTMLVideoElement>(null);
  const balloonVideoRef = useRef<HTMLVideoElement>(null);

  const onRent = useCallback(() => {
    if (!currentUser) {
      return loginModel.onOpen();
    }

    rentModel.onOpen();
  }, [currentUser, loginModel, rentModel]);

  return (
    <div className="fixed top-0 left-0 w-full bg-white z-50 transition-all duration-300 border-b-[1px] shadow-sm">
      <div className={`transition-all duration-300 ${isScrolled ? "py-2" : "py-4"}`}>
        <Container>
          <div className="flex flex-row items-center justify-between gap-3 md:gap-0 relative h-[50px]">
            <div className="flex-none">
              <Logo />
            </div>

            {/* Center Area : Switcher & Compact Search */}
            <div className="hidden md:flex absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 items-center justify-center">

              {/* The Switcher: Logements / Expériences */}
              <div className={`flex flex-row items-center gap-8 text-[17px] text-[#717171] transition-all duration-300 ${isScrolled ? "opacity-0 scale-95 pointer-events-none absolute pt-4" : "opacity-100 scale-100 relative pointer-events-auto"}`}>

                {/* Logements */}
                <div
                  onClick={() => {
                    router.push("/");
                    if (houseVideoRef.current) {
                      houseVideoRef.current.currentTime = 0;
                      houseVideoRef.current.play();
                    }
                  }}
                  onMouseEnter={() => {
                    if (houseVideoRef.current) {
                      houseVideoRef.current.currentTime = 0;
                      houseVideoRef.current.play();
                    }
                  }}
                  className={`cursor-pointer transition relative pb-2 flex flex-row items-center gap-2 hover:text-[#222222] hover:-translate-y-[1px] ${pathname === "/" ? "text-[#222222] font-semibold after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-full after:h-[2px] after:bg-[#222222]" : "font-medium"}`}
                >
                  <video
                    ref={houseVideoRef}
                    autoPlay
                    muted
                    playsInline
                    className="w-10 h-10 object-cover bg-transparent outline-none drop-shadow-sm"
                  >
                    <source src="https://a0.muscache.com/videos/search-bar-icons/webm/house-selected.webm#t=0.001" type="video/webm" />
                    <source src="https://a0.muscache.com/videos/search-bar-icons/hevc/house-selected.mov#t=0.001" type="video/mp4" />
                  </video>
                  <span className="tracking-wide">{t.logements}</span>
                </div>

                {/* Expériences */}
                <div
                  onClick={() => {
                    router.push("/experiences");
                    if (balloonVideoRef.current) {
                      balloonVideoRef.current.currentTime = 0;
                      balloonVideoRef.current.play();
                    }
                  }}
                  onMouseEnter={() => {
                    if (balloonVideoRef.current) {
                      balloonVideoRef.current.currentTime = 0;
                      balloonVideoRef.current.play();
                    }
                  }}
                  className={`cursor-pointer transition relative pb-2 flex flex-row items-center gap-2 hover:text-[#222222] hover:-translate-y-[1px] ${pathname === "/experiences" ? "text-[#222222] font-semibold after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-full after:h-[2px] after:bg-[#222222]" : "font-medium"}`}
                >
                  <video
                    ref={balloonVideoRef}
                    autoPlay
                    muted
                    playsInline
                    className="w-10 h-10 object-cover bg-transparent outline-none drop-shadow-sm"
                  >
                    <source src="https://a0.muscache.com/videos/search-bar-icons/webm/balloon-twirl.webm" type="video/webm" />
                    <source src="https://a0.muscache.com/videos/search-bar-icons/hevc/balloon-twirl.mov" type="video/mp4" />
                  </video>
                  <span className="tracking-wide">{t.experiences}</span>
                </div>

              </div>

              {/* Compact Search Bar (Visible only when scrolled) */}
              <div className={`flex w-auto justify-center transition-all duration-300 ${isScrolled ? "opacity-100 scale-100 translate-y-0 visible relative pointer-events-auto" : "opacity-0 scale-95 translate-y-4 invisible absolute pointer-events-none"}`}>
                 <div
                   onClick={searchModal.onOpen}
                   className="border-[1px] w-full py-1 pl-2 pr-1 rounded-full shadow-md hover:shadow-lg transition cursor-pointer flex flex-row items-center justify-between text-[15px] font-medium text-gray-800 bg-white"
                 >
                   <div className="flex flex-row items-center gap-2 px-3 hover:bg-neutral-100 rounded-full transition py-2">
                     <video
                       autoPlay
                       muted
                       playsInline
                       className="w-5 h-5 object-cover bg-transparent outline-none drop-shadow-sm"
                     >
                       <source src="https://a0.muscache.com/videos/search-bar-icons/webm/house-selected.webm#t=0.001" type="video/webm" />
                       <source src="https://a0.muscache.com/videos/search-bar-icons/hevc/house-selected.mov#t=0.001" type="video/mp4" />
                     </video>
                     <span className="font-semibold">{t.anywhere || "N'importe où"}</span>
                   </div>
                   <div className="px-4 border-l-[1px] border-r-[1px] border-gray-200 flex-1 text-center py-2 hover:bg-neutral-100 rounded-full transition font-semibold">
                     Dates flexibles
                   </div>
                   <div className="flex flex-row items-center gap-3 pl-4 pr-1 py-1 hover:bg-neutral-100 rounded-full transition">
                     <span className="text-gray-500">{t.addguests || "Ajouter des voyageurs"}</span>
                     <div className="p-2 bg-rose-500 rounded-full text-white inline-flex items-center justify-center">
                       <BiSearch size={16} className="font-bold" />
                     </div>
                   </div>
                 </div>
              </div>
            </div>

            <div className="flex flex-row items-center gap-3 flex-none">
              <div
                onClick={onRent}
                className="hidden md:block text-sm font-semibold py-3 px-4 rounded-full hover:bg-neutral-100 transition cursor-pointer"
              >
                {t.host}
              </div>
              <div
                onClick={languageModal.onOpen}
                className="p-3 hover:bg-neutral-100 rounded-full transition cursor-pointer"
                title={language === "fr" ? "Changer la langue" : "Change language"}
              >
                <MdLanguage size={18} />
              </div>
              <UserMenu currentUser={currentUser} />
            </div>
          </div>

          {/* Big Search Bar Area (Hidden when scrolled) */}
          <div className={`flex items-center justify-center transition-all duration-300 origin-top overflow-hidden flex-col ${isScrolled ? "h-0 opacity-0 my-0 scale-y-0" : "h-[80px] opacity-100 my-4 scale-y-100"}`}>
             <Search />
          </div>

        </Container>
      </div>
    </div>
  );
}

export default Navbar;

"use client";

import useCountries from "@/hook/useCountries";
import useSearchModal from "@/hook/useSearchModal";
import { differenceInDays } from "date-fns";
import useLanguage from "@/hook/useLanguage";
import { translations } from "@/lib/translations";
import { useSearchParams } from "next/navigation";
import { useMemo } from "react";
import { BiSearch } from "react-icons/bi";

type Props = {};

function Search({}: Props) {
  const searchModal = useSearchModal();
  const params = useSearchParams();
  const { language } = useLanguage();
  const t = translations[language] || translations.fr;
  const { getByValue } = useCountries();

  const locationValue = params?.get("locationValue");
  const startDate = params?.get("startDate");
  const endDate = params?.get("endDate");
  const guestCount = params?.get("guestCount");

  const locationLabel = useMemo(() => {
    if (locationValue) {
      return locationValue;
    }

    return t.anywhere;
  }, [locationValue, t]);

  const durationLabel = useMemo(() => {
    if (startDate && endDate) {
      const start = new Date(startDate as string);
      const end = new Date(endDate as string);
      let diff = differenceInDays(end, start);

      if (diff === 0) {
        diff = 1;
      }

      return `${diff} ${language === "fr" ? "jours" : "days"}`;
    }

    return t.anyweek;
  }, [startDate, endDate, language, t]);

  const guessLabel = useMemo(() => {
    if (guestCount) {
      return `${guestCount} ${language === "fr" ? "voyageurs" : "guests"}`;
    }

    return t.addguests;
  }, [guestCount, language, t]);

  return (
    <div
      onClick={searchModal.onOpen}
      className="border-[1px] w-full md:w-[850px] py-2 rounded-full shadow-md hover:shadow-lg transition cursor-pointer bg-white"
    >
      <div className="flex flex-row items-center justify-between px-2">

        <div className="flex flex-col px-3 md:px-6 flex-1 border-r-[1px] border-neutral-200">
          <div className="text-[10px] md:text-xs font-bold">Destination</div>
          <div className="text-xs md:text-sm text-neutral-500 truncate max-w-[100px] md:max-w-[200px]">{locationLabel}</div>
        </div>

        <div className="hidden sm:flex flex-col px-6 flex-1 border-r-[1px] border-neutral-200">
           <div className="text-xs font-bold">Dates</div>
           <div className="text-sm text-neutral-500">{durationLabel}</div>
        </div>

        <div className="flex flex-row items-center justify-between pl-3 md:pl-6 pr-2 flex-1">
          <div className="hidden sm:flex flex-col">
            <div className="text-xs font-bold">{language === "fr" ? "Voyageurs" : "Guests"}</div>
            <div className="text-sm text-neutral-500">{guessLabel}</div>
          </div>
          <div className="p-2 md:p-3 bg-rose-500 rounded-full text-white ml-auto flex items-center justify-center h-8 w-8 md:h-12 md:w-12">
            <BiSearch size={18} />
          </div>
        </div>

      </div>
    </div>
  );
}

export default Search;

"use client";

import useCountries from "@/hook/useCountries";
import useSearchModal from "@/hook/useSearchModal";
import { differenceInDays } from "date-fns";
import useLanguage from "@/hook/useLanguage";
import { translations } from "@/lib/translations";
import { useSearchParams } from "next/navigation";
import { useMemo } from "react";
import { BiSearch } from "react-icons/bi";

type Props = {};

function Search({}: Props) {
  const searchModal = useSearchModal();
  const params = useSearchParams();
  const { language } = useLanguage();
  const t = translations[language] || translations.fr;
  const { getByValue } = useCountries();

  const locationValue = params?.get("locationValue");
  const startDate = params?.get("startDate");
  const endDate = params?.get("endDate");
  const guestCount = params?.get("guestCount");

  const locationLabel = useMemo(() => {
    if (locationValue) {
      return locationValue;
    }

    return "Rechercher une destination";
  }, [locationValue]);

  const durationLabel = useMemo(() => {
    if (startDate && endDate) {
      const start = new Date(startDate as string);
      const end = new Date(endDate as string);
      let diff = differenceInDays(end, start);

      if (diff === 0) {
        diff = 1;
      }

      return `${diff} ${language === "fr" ? "jours" : "days"}`;
    }

    return language === "fr" ? "Quand ?" : "Any week";
  }, [startDate, endDate, language]);

  const guessLabel = useMemo(() => {
    if (guestCount) {
      return `${guestCount} ${language === "fr" ? "voyageurs" : "guests"}`;
    }

    return language === "fr" ? "Ajouter des ..." : "Add guests";
  }, [guestCount, language]);

  return (
    <div
      onClick={searchModal.onOpen}
      className="border-[1px] w-full md:w-[850px] py-[6px] pl-8 pr-2 rounded-full shadow-md hover:shadow-lg hover:bg-neutral-100/50 transition cursor-pointer bg-white"
    >
      <div className="flex flex-row items-center justify-between">

        <div className="flex flex-col flex-1 hover:bg-neutral-100 rounded-full py-2 px-6 transition">
          <div className="text-[12px] font-bold text-black">{language === "fr" ? "Destination" : "Where"}</div>
          <div className="text-[14px] text-neutral-500 font-normal truncate max-w-[200px]">{locationLabel}</div>
        </div>

        <div className="h-8 w-[1px] bg-neutral-200"></div>

        <div className="hidden sm:flex flex-col flex-1 hover:bg-neutral-100 rounded-full py-2 px-6 transition">
           <div className="text-[12px] font-bold text-black">{language === "fr" ? "Dates" : "When"}</div>
           <div className="text-[14px] text-neutral-500 font-normal">{durationLabel}</div>
        </div>

        <div className="hidden sm:block h-8 w-[1px] bg-neutral-200"></div>

        <div className="flex flex-row items-center justify-between flex-1 hover:bg-neutral-100 rounded-full py-2 pl-6 pr-2 transition">
          <div className="hidden sm:flex flex-col">
            <div className="text-[12px] font-bold text-black">{language === "fr" ? "Voyageurs" : "Who"}</div>
            <div className="text-[14px] text-neutral-500 font-normal">{guessLabel}</div>
          </div>
          <div className="p-4 bg-[#FF385C] rounded-full text-white ml-auto flex items-center justify-center hover:bg-[#D70466] transition">
            <BiSearch size={20} className="font-bold stroke-[2px]" />
          </div>
        </div>

      </div>
    </div>
  );
}

export default Search;

"use client";

import useLoginModel from "@/hook/useLoginModal";
import useRegisterModal from "@/hook/useRegisterModal";
import useRentModal from "@/hook/useRentModal";
import Image from "next/image";
import { useRouter } from "next/navigation";

import { SafeUser } from "@/types";
import { signOut, useSession } from "next-auth/react";
import { useCallback, useState } from "react";
import useLanguage from "@/hook/useLanguage";
import { translations } from "@/lib/translations";
import { AiOutlineMenu } from "react-icons/ai";
import Avatar from "../Avatar";
import MenuItem from "./MenuItem";

interface Props {
  currentUser?: SafeUser | null;
}

function UserMenu({ currentUser }: Props) {
  const { data: session } = useSession();
  const router = useRouter();
  const registerModel = useRegisterModal();
  const loginModel = useLoginModel();
  const rentModel = useRentModal();
  const [isOpen, setIsOpen] = useState(false);
  const { language } = useLanguage();
  const t = translations[language] || translations.fr;

  const finalUser = currentUser || (session?.user as SafeUser);

  const toggleOpen = useCallback(() => {
    setIsOpen((value) => !value);
  }, []);

  const onRent = useCallback(() => {
    if (!finalUser) {
      return loginModel.onOpen();
    }

    rentModel.onOpen();
  }, [finalUser, loginModel, rentModel]);

  return (
    <div className="relative">
      <div className="flex flex-row items-center gap-3">

        <div
          onClick={toggleOpen}
          className="p-4 md:py-1 md:px-2 border-[1px] flex flex-row items-center gap-3 rounded-full cursor-pointer hover:shadow-md transition"
        >
          <AiOutlineMenu />
          <div className="hidden md:block">
            {finalUser ? (
              <Avatar src={finalUser?.image!} userName={finalUser?.firstname || finalUser?.name} />
            ) : (
              <Image
                className="rounded-full"
                height="30"
                width="30"
                alt="Avatar"
                src="/assets/avatar.png"
              />
            )}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute rounded-xl shadow-md w-[240px] bg-white overflow-hidden right-0 top-12 text-sm border-[1px] border-neutral-100">
          <div className="flex flex-col cursor-pointer">
            {finalUser ? (
              <>
                <MenuItem
                  onClick={() => router.push("/trips")}
                  label={t.bookings}
                />
                <MenuItem
                  onClick={() => router.push("/favorites")}
                  label={t.wishlist}
                />
                <MenuItem
                  onClick={() => router.push("/reservations")}
                  label={t.reservations}
                />
                <MenuItem
                  onClick={() => router.push("/properties")}
                  label={t.properties}
                />

                <MenuItem onClick={onRent} label={t.host} />
                <hr />
                <MenuItem onClick={() => signOut()} label={t.logout} />
              </>
            ) : (
              <>
                <MenuItem onClick={loginModel.onOpen} label={t.login} />
                <MenuItem onClick={registerModel.onOpen} label={t.signup} />
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default UserMenu;

"use client";

import useLoginModel from "@/hook/useLoginModal";
import useRegisterModal from "@/hook/useRegisterModal";
import useRentModal from "@/hook/useRentModal";
import Image from "next/image";
import { useRouter } from "next/navigation";

import { SafeUser } from "@/types";
import { signOut, useSession } from "next-auth/react";
